def advance_finalized_headers(
    path: object,
    documents: object,
    finalities: object,
    anchor: object,
    tip_hash: object,
    trust: object,
) -> dict:
    """Advance a header checkpoint and its finality boundary atomically.

    ``documents``/``anchor``/``tip_hash``/``trust`` are exactly the
